// The English wording of the panel is what the plugin's own Python writes. tests/fixtures/english.json is
// generated by `python tests/test_panel_js.py --write-fixtures` and a Python test fails when it is stale, so
// neither side can drift. Here: the Vue panel, given the structured message, shows exactly Python's text.
import { afterEach, describe, expect, it } from 'vitest';
import fixtures from './fixtures/english.json';
import { mountPanel, type Panel } from './helpers';

let panel: Panel;
afterEach(() => panel?.unmount());

describe('English parity with the plugin', () => {
  it(`shows the Python text for each of the ${fixtures.cases.length} structured messages`, async () => {
    expect(fixtures.cases.length).toBeGreaterThan(40);
    panel = await mountPanel();
    for (const f of fixtures.cases as Array<Record<string, any>>) {
      await panel.deliver({ sync: true, lang: 'en_US', job: 'p', busy: false, error: !!f.error, text: 'EN', msg: f.msg, path: f.path || null, stale: f.stale || '', stale_ref: f.stale_ref || null });
      const want = f.stale ? f.stale : f.text;
      const got = f.stale ? panel.text('#stale') : panel.status();
      expect(got, JSON.stringify(f.msg)).toBe(want);
    }
  });

  it('keeps showing the English text of an older plugin that sends no structured message', async () => {
    panel = await mountPanel({ language: 'pt-BR' });
    await panel.deliver({ sync: true, job: 'p', busy: false, text: 'Legacy English text', msg: null });
    expect(panel.status()).toBe('Legacy English text');
  });
});
